<template>
  <view class="container" v-if="mySelf.memberVipType!=0">
    <view class="phone">{{mySelf.phone}}</view>
    <view class="name">{{mySelf.realName}}</view>
    <view class="qrimg">
      <view class="qrimg-i">
        <tki-qrcode
          cid="qrcode1"
          ref="qrcode"
          :val="val"
          :size="size"
          :onval="onval"
          :loadMake="loadMake"
          :usingComponents="true"
        />
      </view>
    </view>
  </view>
</template>
<script>
import tkiQrcode from "@/components/tki-qrcode/tki-qrcode.vue";
export default {
  data() {
    return {
      user: null,
      mySelf: null,
      val: "",
      size: 200, // 二维码大小
      onval: true, // val值变化时自动重新生成二维码
      loadMake: true, // 组件加载完成后自动生成二维码
      src: "" // 二维码生成后的图片地址或base64
    };
  },
  methods: {
    getMyself: function() {
      uni.request({
        url: `${this.baseUrl}/api/Member/GetSelf`,
        method: "GET",
        header: {
          "Content-Type": "application/json",
          Authorization: `Bearer ` + this.user.token
        },
        success: res => {
          if (res.data.statusCode == 200) {
            this.mySelf = res.data.result;
            this.val = `${
              this.baseUrl
			}/#/pages/reg/invitereg?inviteid=${this.user.id.toString()}`;
			
            if (this.mySelf.memberVipType == 0) {
              uni.showModal({
                title: "提示",
                content: "升级VIP即可分享二维码, 立即升级?",
                success: function(res) {
                  if (res.confirm) {
                    uni.navigateTo({ url: "../user/pay" }); //TODO 导航下载APP
                  } else if (res.cancel) {
                    uni.switchTab({ url: "/pages/user/user" });
                  }
                }
              });
            }
          } else {
            uni.showToast({
              icon: "none",
              title: res.data.msg
            });
          }
        },
        fail: () => {
          uni.showToast({
            icon: "none",
            title: "网络异常"
          });
        }
      });
    }
  },
  components: {
    tkiQrcode
  },
  onLoad: function() {
    this.user = this.getUser("../user/user");
    if (!this.user) {
      return false;
    }

    this.getMyself();

    console.log(this.val);
  },
  onShow:function(){
	   this.getMyself();
  }
};
</script>

